    stellen(l.position, T, P, G.infl); linPath(l.position);
    stellen(l.scale, T, S, G.infl);
    if (e.tin > 0) {
      l.inPoint = e.tin;
      if (e.fade > 0) keys(l.opacity, [e.tin, e.tin + e.fade], [0, 100], 40);
    }
    if (e.tout !== null && e.tout !== undefined) l.outPoint = e.tout;
