  var l = pencil(c, "Kreuz " + zielName, [line2([[b[0] - ox, b[1] - oy], [b[2] + ox, b[3] + oy]]), line2([[b[2] + ox, b[1] - oy], [b[0] - ox, b[3] + oy]])], color || LRED, width || 16, t0, f2s(7));
  l.comment = "ZIEL:" + zielName + "|kreuz";
