  var ds = fxGet(r, "Zettel Schatten"); if (ds) { setP(ds, ["Opacity"], 130); setP(ds, ["Distance"], 10); setP(ds, ["Softness"], 22); }
  attach(t, r); t.position.setValue([-(rc.left + rc.width / 2), -(rc.top + rc.height / 2)]); t.rotation.setValue(0);
