  var T = [], A = [], P = [], S = [];
  for (var j = 0; j < G.keys.length; j++) { var K = G.keys[j]; T.push(K.t); A.push([K.Q[0], K.Q[1]]); P.push([K.P[0], K.P[1]]); S.push([K.z * 100, K.z * 100]); }
