  var l = gFlaeche(c, sid, "FIX Callout " + name, "#000000");
  maskeQ(l, ziel.ell ? gEll(sid, ziel.ell[0], ziel.ell[1], ziel.ell[2], ziel.ell[3], tr) : gPoly(sid, ziel.poly, tr), (ziel.feder || 70) / z, true);
