    var Y0 = -300, Y1 = 2200, voll = [[-400, Y0], [1500, Y0], [1500, Y1], [-400, Y1]], null0 = [[-400, Y0], [1500, Y0], [1500, Y0], [-400, Y0]];
    var a = wisch.art === "weg-oben" ? voll : null0, b = wisch.art === "weg-oben" ? null0 : voll;
