    keys(mw.property("ADBE Mask Shape"), [wisch.t0, wisch.t1], [mkShape(gPoly(sid, a, tr)), mkShape(gPoly(sid, b, tr))], [[20, 20], [70, 70]]);
    noteAnim(null, wisch.t1, l);
