  try { var r = layer.property("ADBE Effect Parade").property("Edge Boil"); if (r) r.remove(); } catch (e) {}
  try { var t = layer.property("ADBE Effect Parade").property("Bleistift fein"); if (t) { var a = findP(t, ["Amount"]), z = findP(t, ["Size"]); if (a) a.setValue(a.value * f); if (z) z.setValue(z.value * f); } } catch (e2) {}
