function aPfeil(c, A, name, a, b, bend, t0, dur, color, w, haupt) { return pfeilEbene(c, A, "Pfeil " + name, bogen(a, b, bend), t0, t0 + (dur || f2s(9)), color, w || 9, null, haupt, "pfeil"); }
