  if (bb) { setP(bb, ["Iterations"], 2); setP(bb, ["Repeat Edge Pixels"], 1); var r = findP(bb, ["Blur Radius"]); if (r) keys(r, [t0, t0 + f2s(4), t1 - f2s(4), t1], [0, 6, 6, 0], 50); }
