  var ds = addFx(r, "ADBE Drop Shadow", "Etikett Schatten"); if (ds) { setP(ds, ["Opacity"], 120); setP(ds, ["Distance"], 6); setP(ds, ["Softness"], 16); }
  r.moveAfter(t);
