return nErr + " Fehler | " + nCut + " ABGESCHNITTEN | " + nKnapp + " KNAPP" + (miss.length ? " | FEHLENDE EFFEKTE: " + miss.join(", ") : " | alle Effekte da") + "\n" + log.join("\n");


